HEAD = '## Sitting 22b — THE COMPILE OF CHAPTER 34, THE DEATH OF MOSES, Deuteronomy 34:1-12 — LEAN'
assert text.startswith(HEAD)
heb = re.findall('[' + chr(0x5d0) + '-' + chr(0x5ea) + ']', text); assert not heb, ('HEBREW SCRIPT IN THE MAP TEXT', len(heb))
